head.script:
scwin.dtsFz530;
scwin.dtsFz531;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        scwin.init();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00600_P8.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    $c.stf.copyDataSet(opener.dts_Fz530, dts_Fz530);
    txb_COND_NM.setValue(opener.dts_Fz530.getCellData(1, "COND_NM"));
    txa_COND_CON.setValue(opener.dts_Fz530.getCellData(1, "COND_CON"));

    // [신규저장] 이면 저장버튼만 활성화하고 [수정저장]이면 다른이름으로저장, 수정 버튼 활성화
    if (opener.txb_conditionTitle.getValue() === "신규저장") {
        // 신규저장
        img_btn_other_save.hide();
        img_btn_modify.hide();
    } else {
        img_Confirm.hide();
        img_btn_other_save.style.left = 263 + 54;
        img_btn_modify.style.left = 362 + 54;
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Close_onclick = async function() {
    try {
        // 닫기버튼 클릭
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00600_P8.img_Close_onclick" });
    }
};

/**
 * @method
 * @name img_Confirm_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Confirm_onclick = async function() {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00600_P8.img_Confirm_onclick" });
    }
};

/**
 * @method
 * @name trs_save_OnSuccess
 * @description save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_save_OnSuccess = async function() {
    try {
        opener.fn_Reset();
        await $c.win.alert($c.stf.getMessageParam("MSG-0001"));
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00600_P8.trs_save_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_save_OnFail
 * @description save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_save_OnFail = async function() {
    try {
        await $c.win.alert(trs_save.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00600_P8.trs_save_OnFail" });
    }
};

/**
 * @method
 * @name img_btn_other_save_onclick
 * @description 「다른이름으로저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_btn_other_save_onclick = async function() {
    try {
        await scwin.duplicateSave();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00600_P8.img_btn_other_save_onclick" });
    }
};

/**
 * @method
 * @name img_btn_modify_onclick
 * @description 「수정」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_btn_modify_onclick = async function() {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00600_P8.img_btn_modify_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name save
 * @description 신규 저장
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    // 저장될 데이터를 세팅.
    scwin.setSaveData();
    if (!$c.cp.isModified(dts_Fz530)) {
        await $c.win.alert("변경된 데이터가 없습니다.");
        return false;
    }

    // 필수 체크.
    if (!await scwin.chkValid()) {
        return;
    }
    if (!confirm("저장하시겠습니까?")) {
        return;
    }
    if (opener.txb_conditionTitle.getValue() === "신규저장") {
        // 신규저장

        trs_save.KeyName = "toinb_dataid4";
        // trs_save.Parameters    = "EMP_NO=" + js_emp_no +",EMP_NM=" + js_emp_nm;
        const sbmOptions = {
            id : "sbm_trs_save",
            action : "/ConditionSrchAction.do",
            ref : "dts_Fz530",
            target : "trs_save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    } else {
        // 조건읽기를 했을경우

        trs_save.KeyName = "toinb_dataid4";
        // trs_save.Parameters    = "EMP_NO=" + js_emp_no +",EMP_NM=" + js_emp_nm;
        const sbmOptions = {
            id : "sbm_trs_save",
            action : "/ConditionSrchAction.do",
            ref : "dts_Fz530",
            target : "trs_save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name duplicateSave
 * @description 다른 이름으로 저장
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.duplicateSave = async function() {
    // 저장될 데이터를 세팅.
    scwin.setSaveData();
    if (!$c.cp.isModified(dts_Fz530)) {
        await $c.win.alert("변경된 데이터가 없습니다.");
        return false;
    }

    // 필수 체크.
    if (!await scwin.chkValid()) {
        return false;
    }
    if (!confirm("다른 이름으로 저장하시겠습니까?")) {
        return false;
    }
    trs_save.KeyName = "toinb_dataid4";
    // trs_save.Parameters    = "EMP_NO=" + js_emp_no +",EMP_NM=" + js_emp_nm;
    const sbmOptions = {
        id : "sbm_trs_save",
        action : "/ConditionSrchAction.do",
        ref : "dts_Fz530",
        target : "trs_save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name chkValid
 * @description 유효성 체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkValid = async function() {
    if (txb_COND_NM.getValue() === "") {
        await $c.win.alert("제목을 입력하세요.");
        txb_COND_NM.focus();
        return false;
    }
    if (txa_COND_CON.getValue() === "") {
        await $c.win.alert("상세내용을 입력하세요.");
        txa_COND_CON.Focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name setSaveData
 * @description 저장될 데이터를 세팅한다.
 * @returns {void}
 * @hidden N
 */
scwin.setSaveData = function() {
    dts_Fz530.setCellData(1, "COND_NM", txb_COND_NM.getValue()); // 제목 : 저장팝업에서 세팅
    dts_Fz530.setCellData(1, "COND_CON", txa_COND_CON.getValue()); // 상세내용 : 저장팝업에서 세팅

};
